    /// cas-eaf8: a worker branch is a long-lived execution lane, not a
    /// task receipt. Once task A's recorded anchor is merged into epic 1,
    /// later task B work for epic 2 on the same live branch must not
    /// re-strand epic 1.
    #[test]
    fn epic_close_uses_child_anchor_when_worker_branch_is_reused() {
        let dir = init_epic_repo(&[("worker", 1)]);
        let p = dir.path();
        let task_a_anchor = epic_git_stdout(p, &["rev-parse", "factory/worker"]);

        // Integrate task A into epic 1 (represented by main).
        git(p, &["merge", "-q", "--no-ff", "factory/worker"]);

        // Reuse the worker's one long-lived branch for task B on epic 2.
        git(p, &["checkout", "-q", "factory/worker"]);
        std::fs::write(p.join("task-b.rs"), "// unrelated epic 2 work\n").unwrap();
        git(p, &["add", "task-b.rs"]);
        git(p, &["commit", "-q", "-m", "feat: task B on epic 2"]);

        assert_eq!(
            count_unmerged_factory_commits(p, "factory/worker", "main"),
            1,
            "precondition: the reused live branch carries epic 2 work"
        );
        assert!(
            commit_is_merged_into_parent(p, &task_a_anchor, "main"),
            "precondition: task A's own anchor is merged into epic 1"
        );

        let mut task_a = child("cas-task-a", TaskStatus::Closed, Some("worker"));
        task_a.deliverables.factory_branch_anchor = Some(task_a_anchor);
        task_a.deliverables.parked_branch = Some("factory/worker".to_string());
        let task = epic("cas-epic-1");
        let req = base_req(&task.id);

        let out = run_epic_close_merge_gate(&task, &req, "main", p, &[task_a]);
        assert!(
            matches!(
                out,
                EpicCloseGateOutcome::Proceed | EpicCloseGateOutcome::ProceedWithNote(_)
            ),
            "epic 1 must close based on task A's merged anchor, regardless of \
             task B's later commit on the reused worker branch; got {out:?}"
        );
    }

    #[test]
    fn epic_close_accepts_merged_live_tip_when_recorded_anchor_was_superseded() {
        let dir = init_epic_repo(&[("worker", 1)]);
        let p = dir.path();
        let recorded_anchor = epic_git_stdout(p, &["rev-parse", "factory/worker"]);

        git(p, &["checkout", "-q", "factory/worker"]);
        git(
            p,
            &[
                "commit",
                "-q",
                "--amend",
                "-m",
                "feat: worker patch with amended metadata",
            ],
        );
        let live_tip = epic_git_stdout(p, &["rev-parse", "HEAD"]);
        assert_ne!(recorded_anchor, live_tip);
        assert!(
            git_ref_exists(p, &recorded_anchor),
            "the superseded commit object must remain resolvable"
        );

        let remote = tempfile::tempdir().unwrap();
        git(remote.path(), &["init", "-q", "--bare"]);
        git(
            p,
            &["remote", "add", "origin", remote.path().to_str().unwrap()],
        );
        git(p, &["push", "-q", "-u", "origin", "factory/worker"]);
        git(p, &["checkout", "-q", "main"]);
        git(
            p,
            &[
                "merge",
                "-q",
                "--no-ff",
                "-m",
                "merge amended tip",
                "factory/worker",
            ],
        );

        assert_eq!(
            count_unmerged_factory_commits(p, &recorded_anchor, "main"),
            1,
            "precondition: the superseded recorded commit is not an ancestor of main"
        );
        assert!(matches!(
            known_unmerged_factory_commits(p, "factory/worker", "main"),
            KnownUnmergedCount::KnownZero
        ));
        assert!(matches!(
            known_unmerged_factory_commits(p, "origin/factory/worker", "main"),
            KnownUnmergedCount::KnownZero
        ));

        let mut child = child("cas-superseded-anchor", TaskStatus::Closed, Some("worker"));
        child.deliverables.factory_branch_anchor = Some(recorded_anchor.clone());
        child.deliverables.parked_branch = Some("factory/worker".to_string());
        let task = epic("cas-epic-superseded-anchor");
        let req = base_req(&task.id);

        match run_epic_close_merge_gate(&task, &req, "main", p, &[child.clone()]) {
            EpicCloseGateOutcome::ProceedWithNote(note) => {
                assert!(note.contains(&recorded_anchor), "{note}");
                assert!(
                    note.contains(&live_tip) || note.contains("accepted squash re-anchor"),
                    "{note}"
                );
                assert!(
                    note.contains("superseded") || note.contains("task-specific effect survives"),
                    "{note}"
                );
            }
            other => panic!("merged live tip must clear a superseded anchor; got {other:?}"),
        }

        let statuses = collect_epic_branch_statuses(&[child], "main", p);
        let report = render_epic_status_report(&task.id, "main", &statuses);
        assert!(
            report.contains("Recorded/live merge-evidence reconciliation"),
            "{report}"
        );
        assert!(report.contains(&recorded_anchor), "{report}");
        assert!(report.contains("factory/worker"), "{report}");
        assert!(
            report.contains(&live_tip) || report.contains("accepted squash re-anchor"),
            "{report}"
        );
    }

    /// GH #404 / cas-32ee: an epic integration squash can carry a child's
    /// patch, followed by a routine bundle rebuild that changes the same file.
    /// The original factory anchor is no longer an ancestor, so epic close
    /// must re-anchor at the accepted squash and reuse child-close evolution
    /// proof instead of reporting the old anchor as stranded.
    #[test]
    fn epic_close_accepts_squash_then_evolved_child_and_uses_live_lane_count_cas_32ee() {
        let dir = init_epic_repo(&[]);
        let p = dir.path();

        git(p, &["checkout", "-q", "main"]);
        std::fs::create_dir_all(p.join("hub-web/dist")).unwrap();
        std::fs::write(p.join("hub-web/dist/app.js"), "const version = 'base';\n").unwrap();
        git(p, &["add", "hub-web/dist/app.js"]);
        git(p, &["commit", "-q", "-m", "build: seed Commander bundle"]);
        git(p, &["branch", "-f", "factory/worker", "main"]);
        git(p, &["checkout", "-q", "factory/worker"]);

        std::fs::write(
            p.join("hub-web/dist/app.js"),
            "const version = 'delivered-child';\n",
        )
        .unwrap();
        git(p, &["add", "hub-web/dist/app.js"]);
        git(
            p,
            &[
                "commit",
                "-q",
                "-m",
                "fix(cas-child): ship Commander change",
            ],
        );
        let anchor = epic_git_stdout(p, &["rev-parse", "HEAD"]);

        git(p, &["checkout", "-q", "main"]);
        git(p, &["merge", "--squash", "factory/worker"]);
        git(
            p,
            &[
                "commit",
                "-q",
                "-m",
                "integrate: Commander child batch (cas-child)",
            ],
        );
        let integration = epic_git_stdout(p, &["rev-parse", "HEAD"]);

        std::fs::write(
            p.join("hub-web/dist/app.js"),
            "const version = 'rebuilt-after-integration';\n",
        )
        .unwrap();
        git(p, &["add", "hub-web/dist/app.js"]);
        git(
            p,
            &[
                "commit",
                "-q",
                "-m",
                "build: rebuild Commander bundle after integration",
            ],
        );
        let rebuild = epic_git_stdout(p, &["rev-parse", "HEAD"]);

        // A factory lane can be realigned after delivery. Its current tip is
        // the only valid stranded-count source; the preserved anchor remains
        // delivery evidence and must not contribute a stale count.
        git(p, &["branch", "-f", "factory/worker", "main"]);
        assert_eq!(
            count_unmerged_factory_commits(p, "factory/worker", "main"),
            0,
            "precondition: the live lane is fully integrated"
        );
        assert!(
            count_unmerged_factory_commits(p, &anchor, "main") > 0,
            "precondition: the historical squash anchor remains non-ancestral"
        );

        assert_eq!(
            reanchored_delivery_content_in_parent(p, &anchor, "main"),
            Some(ReanchoredDeliveryContent::Superseded {
                integration: integration.clone(),
                paths: vec!["hub-web/dist/app.js".to_string()],
                commits: vec![rebuild.clone()],
            })
        );

        let mut child = child("cas-child", TaskStatus::Closed, Some("worker"));
        child.deliverables.factory_branch_anchor = Some(anchor.clone());
        child.deliverables.parked_branch = Some("factory/worker".to_string());
        let statuses = collect_epic_branch_statuses(std::slice::from_ref(&child), "main", p);
        let row = &statuses[0];
        assert_eq!(row.unmerged_count, 0, "{row:?}");
        assert_eq!(row.checked_refs_label(), "factory/worker");
        let evolution = row
            .content_evolution_note
            .as_deref()
            .expect("the squash re-anchor and rebuild must be named");
        assert!(evolution.contains(&integration), "{evolution}");
        assert!(evolution.contains(&rebuild), "{evolution}");

        match run_epic_close_merge_gate(
            &epic("cas-epic-evolved-squash"),
            &base_req("cas-epic-evolved-squash"),
            "main",
            p,
            &[child],
        ) {
            EpicCloseGateOutcome::ProceedWithNote(note) => {
                assert!(note.contains(&integration), "{note}");
                assert!(note.contains(&rebuild), "{note}");
            }
            other => panic!("evolved squash child must not strand the epic: {other:?}"),
        }
    }

    #[test]
    fn squash_merged_child_anchors_reconcile_before_stranded_summary_cas_65e0() {
        let dir = init_epic_repo(&[("alpha", 1), ("bravo", 1), ("charlie", 1)]);
        let bare = tempfile::tempdir().unwrap();
        let p = dir.path();
        let local_parent_before_prs = epic_git_stdout(p, &["rev-parse", "main"]);
        let alpha_anchor = epic_git_stdout(p, &["rev-parse", "factory/alpha"]);
        let bravo_anchor = epic_git_stdout(p, &["rev-parse", "factory/bravo"]);
        let charlie_anchor = epic_git_stdout(p, &["rev-parse", "factory/charlie"]);
        add_origin(p, bare.path());

        // GitHub's squash button leaves both factory refs and their recorded
        // anchors non-ancestral even though their content is now on main.
        for worker in ["alpha", "bravo"] {
            git(
                p,
                &["merge", "-q", "--squash", &format!("factory/{worker}")],
            );
            git(p, &["commit", "-q", "-m", &format!("squash {worker}")]);
        }
        git(p, &["push", "-q", "origin", "main"]);
        git(p, &["reset", "-q", "--hard", &local_parent_before_prs]);

        assert!(count_unmerged_factory_commits(p, &alpha_anchor, "main") > 0);
        assert!(count_unmerged_factory_commits(p, &bravo_anchor, "main") > 0);
        assert!(
            commit_tip_tree_reachable_from(p, &alpha_anchor, "origin/main"),
            "the first squash preserves alpha's exact tip tree in remote parent history"
        );
        assert!(
            anchor_work_patches_equivalent_on_parent(p, &bravo_anchor, "origin/main"),
            "the later squash preserves bravo's patch even though main also carries alpha"
        );
        assert!(
            !anchor_work_patches_equivalent_on_parent(p, &charlie_anchor, "origin/main"),
            "charlie is the genuinely absent control"
        );

        let mut alpha = child("cas-alpha", TaskStatus::Closed, Some("alpha"));
        alpha.deliverables.factory_branch_anchor = Some(alpha_anchor);
        let mut bravo = child("cas-bravo", TaskStatus::Closed, Some("bravo"));
        bravo.deliverables.factory_branch_anchor = Some(bravo_anchor);
        let mut charlie = child("cas-charlie", TaskStatus::Closed, Some("charlie"));
        charlie.deliverables.factory_branch_anchor = Some(charlie_anchor);
        let children = vec![alpha, bravo, charlie];

        let statuses = collect_epic_branch_statuses(&children, "main", p);
        let by_id: std::collections::HashMap<_, _> = statuses
            .iter()
            .map(|row| (row.task_id.as_str(), row))
            .collect();
        assert_eq!(
            by_id["cas-alpha"].unmerged_count, 0,
            "tree-identical squash content must reconcile even while the factory ref stays non-ancestral"
        );
        assert_eq!(
            by_id["cas-bravo"].unmerged_count, 0,
            "patch-equivalent squash content must reconcile independently for every child"
        );
        assert!(
            by_id["cas-charlie"].unmerged_count > 0,
            "affirmatively absent content must remain stranded"
        );

        let report = render_epic_status_report("cas-epic", "main", &statuses);
        assert_eq!(
            report
                .lines()
                .filter(|line| {
                    line.starts_with("| cas-") && line.contains("merged (squash, ancestry lost)")
                })
                .count(),
            2,
            "each proven squash merge must be named explicitly: {report}"
        );
        assert!(
            report.contains("1 child task(s) carry stranded factory commits"),
            "only the genuinely absent child may receive hard-block wording: {report}"
        );

        let squash_only = &children[..2];
        assert!(matches!(
            run_epic_close_merge_gate(
                &epic("cas-epic-squash"),
                &base_req("cas-epic-squash"),
                "main",
                p,
                squash_only,
            ),
            EpicCloseGateOutcome::ProceedWithNote(_)
        ));

        match run_epic_close_merge_gate(
            &epic("cas-epic-mixed"),
            &base_req("cas-epic-mixed"),
            "main",
            p,
            &children,
        ) {
            EpicCloseGateOutcome::Reject(message) => {
                assert!(message.contains("cas-charlie"), "{message}");
                assert!(!message.contains("cas-alpha"), "{message}");
                assert!(!message.contains("cas-bravo"), "{message}");
            }
            other => panic!("the absent child must still block epic close, got {other:?}"),
        }
    }

    #[test]
    fn epic_close_rejects_recycled_worker_branch_that_does_not_prove_old_anchor() {
        let dir = init_epic_repo(&[("worker", 1)]);
        let p = dir.path();
        let stranded_anchor = epic_git_stdout(p, &["rev-parse", "factory/worker"]);

        git(p, &["branch", "-D", "factory/worker"]);
        git(p, &["checkout", "-q", "-b", "factory/worker", "main"]);
        std::fs::write(
            p.join("replacement-task.rs"),
            "// unrelated replacement work\n",
        )
        .unwrap();
        git(p, &["add", "replacement-task.rs"]);
        git(p, &["commit", "-q", "-m", "feat: replacement task"]);
        git(p, &["checkout", "-q", "main"]);
        git(
            p,
            &[
                "merge",
                "-q",
                "--no-ff",
                "-m",
                "merge replacement task",
                "factory/worker",
            ],
        );

        assert!(git_ref_exists(p, &stranded_anchor));
        assert_eq!(
            count_unmerged_factory_commits(p, &stranded_anchor, "main"),
            1
        );
        assert!(matches!(
            known_unmerged_factory_commits(p, "factory/worker", "main"),
            KnownUnmergedCount::KnownZero
        ));

        let mut child = child("cas-recycled-worker", TaskStatus::Closed, Some("worker"));
        child.deliverables.factory_branch_anchor = Some(stranded_anchor.clone());
        let task = epic("cas-epic-recycled-worker");
        match run_epic_close_merge_gate(&task, &base_req(&task.id), "main", p, &[child]) {
            EpicCloseGateOutcome::Reject(message) => {
                assert!(message.contains(&stranded_anchor), "{message}");
            }
            other => panic!("a recycled branch cannot prove the old task; got {other:?}"),
        }
    }

    #[test]
    fn epic_close_rejects_worker_branch_reset_to_parent_without_anchor_content() {
        let dir = init_epic_repo(&[("worker", 1)]);
        let p = dir.path();
        let stranded_anchor = epic_git_stdout(p, &["rev-parse", "factory/worker"]);
        git(p, &["branch", "-f", "factory/worker", "main"]);

        assert!(git_ref_exists(p, &stranded_anchor));
        assert_eq!(
            count_unmerged_factory_commits(p, &stranded_anchor, "main"),
            1
        );
        assert!(matches!(
            known_unmerged_factory_commits(p, "factory/worker", "main"),
            KnownUnmergedCount::KnownZero
        ));

        let mut child = child("cas-reset-worker", TaskStatus::Closed, Some("worker"));
        child.deliverables.factory_branch_anchor = Some(stranded_anchor.clone());
        let task = epic("cas-epic-reset-worker");
        match run_epic_close_merge_gate(&task, &base_req(&task.id), "main", p, &[child]) {
            EpicCloseGateOutcome::Reject(message) => {
                assert!(message.contains(&stranded_anchor), "{message}");
            }
            other => panic!("reset-to-parent cannot prove the task was merged; got {other:?}"),
        }
    }

    #[test]
    fn epic_close_accepts_content_proof_when_parked_branch_vanished() {
        let dir = init_epic_repo(&[("alice", 1), ("bob", 0)]);
        let p = dir.path();
        let stranded_anchor = epic_git_stdout(p, &["rev-parse", "factory/alice"]);
        git(p, &["cherry-pick", "--no-commit", &stranded_anchor]);
        git(
            p,
            &[
                "commit",
                "-q",
                "-m",
                "integrate alice patch under rewritten commit",
            ],
        );
        git(p, &["branch", "-D", "factory/alice"]);

        assert_eq!(
            count_unmerged_factory_commits(p, &stranded_anchor, "main"),
            1,
            "the recorded SHA remains non-ancestral"
        );
        assert!(
            commit_patches_cherry_equivalent_on_parent(p, &stranded_anchor, "main"),
            "the anchor has task-specific content proof, so only the vanished \
             parked branch should prevent reconciliation"
        );
        assert!(matches!(
            known_unmerged_factory_commits(p, "factory/bob", "main"),
            KnownUnmergedCount::KnownZero
        ));

        let mut reassigned = child("cas-missing-parked", TaskStatus::Closed, Some("bob"));
        reassigned.deliverables.parked_branch = Some("factory/alice".to_string());
        reassigned.deliverables.factory_branch_anchor = Some(stranded_anchor.clone());
        let task = epic("cas-epic-missing-parked");
        match run_epic_close_merge_gate(&task, &base_req(&task.id), "main", p, &[reassigned]) {
            EpicCloseGateOutcome::ProceedWithNote(note) => {
                assert!(note.contains(&stranded_anchor), "{note}");
                assert!(
                    note.contains("factory/alice unresolved")
                        || note.contains("accepted squash re-anchor"),
                    "{note}"
                );
                assert!(
                    note.contains("task-specific content is proven")
                        || note.contains("task-specific effect survives"),
                    "{note}"
                );
            }
            other => panic!(
                "affirmative anchor content proof must outrank a vanished historical branch; got {other:?}"
            ),
        }
    }

    /// cas-eaf8: task-specific anchoring must retain the guard's teeth.
    /// A child's own recorded anchor that is not on the epic branch still
    /// hard-blocks epic close.
    #[test]
    fn epic_close_rejects_genuinely_unmerged_child_anchor() {
        let dir = init_epic_repo(&[("worker", 1)]);
        let p = dir.path();
        let unmerged_anchor = epic_git_stdout(p, &["rev-parse", "factory/worker"]);
        let mut child = child("cas-unmerged", TaskStatus::Closed, Some("worker"));
        child.deliverables.factory_branch_anchor = Some(unmerged_anchor);
        child.deliverables.parked_branch = Some("factory/worker".to_string());
        let task = epic("cas-epic-blocked");
        let req = base_req(&task.id);

        match run_epic_close_merge_gate(&task, &req, "main", p, &[child]) {
            EpicCloseGateOutcome::Reject(msg) => {
                assert!(msg.contains("MERGE REQUIRED"), "missing hard block: {msg}");
                assert!(msg.contains("cas-unmerged"), "missing child id: {msg}");
                assert!(
                    msg.contains("factory/worker"),
                    "missing parked branch: {msg}"
                );
            }
            other => panic!("genuinely unmerged child anchor must Reject, got {other:?}"),
        }
    }

    #[test]
    fn epic_close_with_bypass_still_rejects_on_unmerged_child() {
        // Bypass-immunity at the structural level — gate has no
        // bypass parameter — and behavioral level — even with
        // bypass=Some(true) on the request, the gate rejects.
        let dir = init_epic_repo(&[("alpha", 1)]);
        let subtasks = vec![child("cas-c1", TaskStatus::InProgress, Some("alpha"))];
        let task = epic("cas-epic-bypass");
        let mut req = base_req(&task.id);
        req.supervisor_override = Some(true);
        req.reason = Some("supervisor wants to skip review".to_string());

        let out = run_epic_close_merge_gate(&task, &req, "main", dir.path(), &subtasks);
        match out {
            EpicCloseGateOutcome::Reject(msg) => {
                assert!(
                    msg.contains("supervisor_override=true"),
                    "rejection must spell out bypass-immunity policy: {msg}"
                );
            }
            other => panic!("supervisor_override must NOT skip the epic merge gate, got {other:?}"),
        }
    }

    #[test]
    fn epic_close_gate_skips_non_epic_tasks() {
        // Symmetrical to cas-95ce's per-task gate: this one only fires
        // on Epic-type tasks.
        let dir = init_epic_repo(&[("alpha", 5)]);
        let subtasks = vec![child("cas-c1", TaskStatus::InProgress, Some("alpha"))];
        let task = child("cas-not-epic", TaskStatus::InProgress, None); // non-epic
        let req = base_req(&task.id);

        let out = run_epic_close_merge_gate(&task, &req, "main", dir.path(), &subtasks);
        assert!(
            matches!(out, EpicCloseGateOutcome::Proceed),
            "non-epic task must skip this gate, got {out:?}"
        );
    }

